// Parse Claude API response and Notion data
const newsResponse = $items('Claude: News Collector')[0]?.json || {};
const notionResponse = $items('Read Notion Published')[0]?.json || {};

// Extract news content from Claude response
let newsData = {};
if (newsResponse.content && Array.isArray(newsResponse.content)) {
  const textBlock = newsResponse.content.find(block => block.type === 'text');
  if (textBlock?.text) {
    try {
      // Clean and parse JSON
      let jsonText = textBlock.text
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();
      const firstBrace = jsonText.indexOf('{');
      const lastBrace = jsonText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        jsonText = jsonText.slice(firstBrace, lastBrace + 1);
      }
      newsData = JSON.parse(jsonText);
    } catch (e) {
      console.error('Failed to parse news data:', e);
      newsData = { error: 'Failed to parse', raw: textBlock.text };
    }
  }
}

// Extract published slugs from Notion
const publishedSlugs = [];
const publishedTitles = [];
if (notionResponse.results && Array.isArray(notionResponse.results)) {
  notionResponse.results.forEach(page => {
    // Extract slug
    const slugProp = page.properties?.Slug?.rich_text?.[0]?.plain_text;
    if (slugProp) publishedSlugs.push(slugProp.toLowerCase());

    // Extract title
    const titleProp = page.properties?.Title?.title?.[0]?.plain_text;
    if (titleProp) publishedTitles.push(titleProp.toLowerCase());
  });
}

// Get content opportunities
const opportunities = newsData.content_opportunities || [];

return [{
  json: {
    news_data: newsData,
    published_slugs: publishedSlugs.join(', '),
    published_titles: publishedTitles.slice(0, 20).join(' | '),
    published_count: publishedSlugs.length,
    opportunities: opportunities,
    collection_date: newsData.collection_date || new Date().toISOString().split('T')[0]
  }
}];

// Parse topic selection from Claude response
const response = $input.first().json;
let topicData = {};

if (response.content && Array.isArray(response.content)) {
  const textBlock = response.content.find(block => block.type === 'text');
  if (textBlock?.text) {
    try {
      let jsonText = textBlock.text
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();
      const firstBrace = jsonText.indexOf('{');
      const lastBrace = jsonText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        jsonText = jsonText.slice(firstBrace, lastBrace + 1);
      }
      topicData = JSON.parse(jsonText);
    } catch (e) {
      console.error('Failed to parse topic data:', e);
      throw new Error('Failed to parse topic selection: ' + e.message);
    }
  }
}

if (!topicData.selected_topic) {
  throw new Error('No topic selected by Claude');
}

const topic = topicData.selected_topic;

// Get previous node data
const prevData = $items('Process News & Notion Data')[0]?.json || {};

return [{
  json: {
    topic: topic,
    backup_topics: topicData.backup_topics || [],
    news_data: prevData.news_data || {},
    collection_date: prevData.collection_date
  }
}];

// Parse Korean blog content from Claude response
const response = $input.first().json;
let blogData = {};

if (response.content && Array.isArray(response.content)) {
  const textBlock = response.content.find(block => block.type === 'text');
  if (textBlock?.text) {
    try {
      let jsonText = textBlock.text
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();
      const firstBrace = jsonText.indexOf('{');
      const lastBrace = jsonText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        jsonText = jsonText.slice(firstBrace, lastBrace + 1);
      }
      blogData = JSON.parse(jsonText);
    } catch (e) {
      console.error('Failed to parse Korean blog:', e);
      throw new Error('Failed to parse Korean blog content');
    }
  }
}

// Convert markdown to Notion blocks
function markdownToNotionBlocks(markdown) {
  const lines = markdown.split('\n');
  const blocks = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Skip H1 (it's the title, handled in properties)
    if (line.startsWith('# ')) {
      i++;
      continue;
    }

    // H2 Heading
    if (line.startsWith('## ')) {
      blocks.push({
        object: 'block',
        type: 'heading_2',
        heading_2: {
          rich_text: [{ type: 'text', text: { content: line.slice(3).trim() } }]
        }
      });
      i++;
      continue;
    }

    // H3 Heading
    if (line.startsWith('### ')) {
      blocks.push({
        object: 'block',
        type: 'heading_3',
        heading_3: {
          rich_text: [{ type: 'text', text: { content: line.slice(4).trim() } }]
        }
      });
      i++;
      continue;
    }

    // Bulleted list
    if (line.startsWith('- ') || line.startsWith('* ')) {
      blocks.push({
        object: 'block',
        type: 'bulleted_list_item',
        bulleted_list_item: {
          rich_text: [{ type: 'text', text: { content: line.slice(2).trim() } }]
        }
      });
      i++;
      continue;
    }

    // Numbered list
    if (/^\d+\.\s/.test(line)) {
      const content = line.replace(/^\d+\.\s/, '').trim();
      blocks.push({
        object: 'block',
        type: 'numbered_list_item',
        numbered_list_item: {
          rich_text: [{ type: 'text', text: { content: content } }]
        }
      });
      i++;
      continue;
    }

    // FAQ Question (bold Q:)
    if (line.startsWith('**Q:') || line.startsWith('**Q.')) {
      const question = line.replace(/\*\*/g, '').trim();
      // Look for answer on next line(s)
      let answer = '';
      i++;
      while (i < lines.length && !lines[i].startsWith('**Q')) {
        if (lines[i].startsWith('A:') || lines[i].startsWith('A.')) {
          answer = lines[i].replace(/^A[:.] ?/, '').trim();
        } else if (lines[i].trim() && !lines[i].startsWith('#')) {
          answer += ' ' + lines[i].trim();
        }
        i++;
      }

      blocks.push({
        object: 'block',
        type: 'toggle',
        toggle: {
          rich_text: [{ type: 'text', text: { content: question } }],
          children: [{
            object: 'block',
            type: 'paragraph',
            paragraph: {
              rich_text: [{ type: 'text', text: { content: answer.trim() } }]
            }
          }]
        }
      });
      continue;
    }

    // Blockquote / Callout
    if (line.startsWith('> ')) {
      blocks.push({
        object: 'block',
        type: 'callout',
        callout: {
          rich_text: [{ type: 'text', text: { content: line.slice(2).trim() } }],
          icon: { emoji: '💡' }
        }
      });
      i++;
      continue;
    }

    // Regular paragraph (non-empty)
    if (line.trim() !== '') {
      // Handle inline formatting
      let richText = [];
      let text = line.trim();

      // Simple approach: just use plain text for now
      // Could be enhanced to handle **bold**, *italic*, [links](url)
      richText.push({ type: 'text', text: { content: text } });

      blocks.push({
        object: 'block',
        type: 'paragraph',
        paragraph: {
          rich_text: richText
        }
      });
    }

    i++;
  }

  // Notion API has a limit of 100 blocks per request
  return blocks.slice(0, 100);
}

const notionBlocks = markdownToNotionBlocks(blogData.content_markdown || '');

// Calculate word count
const wordCount = (blogData.content_markdown || '').split(/\s+/).length;

return [{
  json: {
    ...blogData,
    word_count: wordCount,
    notion_blocks: notionBlocks,
    blocks_count: notionBlocks.length
  }
}];

// Parse English blog content from Claude response
const response = $input.first().json;
let blogData = {};

if (response.content && Array.isArray(response.content)) {
  const textBlock = response.content.find(block => block.type === 'text');
  if (textBlock?.text) {
    try {
      let jsonText = textBlock.text
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();
      const firstBrace = jsonText.indexOf('{');
      const lastBrace = jsonText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        jsonText = jsonText.slice(firstBrace, lastBrace + 1);
      }
      blogData = JSON.parse(jsonText);
    } catch (e) {
      console.error('Failed to parse English blog:', e);
      throw new Error('Failed to parse English blog content');
    }
  }
}

