// Compile final report
const koUpload = $items('Notion Upload KO')[0]?.json || {};
const enUpload = $items('Notion Upload EN')[0]?.json || {};
const koBlog = $items('Parse & Convert KO Blog')[0]?.json || {};
const enBlog = $items('Parse & Convert EN Blog')[0]?.json || {};
const topicData = $items('Parse Topic Selection')[0]?.json || {};

const report = {
  timestamp: new Date().toISOString(),
  status: 'completed',
  topic: {
    title_ko: topicData.topic?.title_ko || koBlog.title,
    title_en: topicData.topic?.title_en || enBlog.title,
    slug: koBlog.slug || enBlog.slug,
    selection_reason: topicData.topic?.selection_reason
  },
  korean_blog: {
    title: koBlog.title,
    word_count: koBlog.word_count,
    category: koBlog.category,
    tags: koBlog.tags,
    notion_page_id: koUpload.id,
    notion_url: koUpload.url,
    status: koUpload.id ? 'uploaded' : 'failed'
  },
  english_blog: {
    title: enBlog.title,
    word_count: enBlog.word_count,
    category: enBlog.category,
    tags: enBlog.tags,
    notion_page_id: enUpload.id,
    notion_url: enUpload.url,
    status: enUpload.id ? 'uploaded' : 'failed'
  },
  backup_topics: topicData.backup_topics || [],
  summary: `Created blog posts: KO (${koBlog.word_count} words), EN (${enBlog.word_count} words). Topic: ${koBlog.title || enBlog.title}`
};

return [{ json: report }];
